+      backdrop-filter: blur(16px);
+      padding: 32px;
+    }
+
+    h1 {
+      margin: 0 0 12px;
+      font-size: clamp(2rem, 4vw, 3rem);
+      line-height: 1.05;
+    }
+
+    .intro {
+      margin: 0 0 28px;
+      color: var(--muted);
+      font-size: 1.05rem;
+      line-height: 1.7;
+      max-width: 62ch;
+    }
+
+    .faq {
+      display: grid;
+      gap: 16px;
+    }
+
+    .example {
+      border: 1px solid rgba(125, 211, 252, 0.16);
+      border-radius: 18px;
+      background: linear-gradient(180deg, rgba(15, 23, 42, 0.96), rgba(15, 23, 42, 0.84));
+      overflow: hidden;
+      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
+    }
+
+    .example:hover,
+    .example:focus-within {
+      border-color: rgba(125, 211, 252, 0.34);
+      transform: translateY(-1px);
+      box-shadow: 0 14px 30px rgba(15, 23, 42, 0.32);
+    }
+
+    .question {
+      width: 100%;
+      border: 0;
+      background: transparent;
+      color: var(--text);
+      padding: 20px 22px;
+      text-align: left;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 20px;
+      font: inherit;
+      font-size: 1.05rem;
+      font-weight: 700;
+      cursor: pointer;
+    }
+
+    .question:focus-visible {
+      outline: 2px solid var(--accent);
+      outline-offset: -2px;
+    }
+
+    .icon {
+      color: var(--accent);
+      font-size: 1.4rem;
+      line-height: 1;
+      transition: transform 0.2s ease, color 0.2s ease;
+      flex-shrink: 0;
+    }
+
+    .question[aria-expanded="true"] .icon {
+      transform: rotate(45deg);
+      color: var(--accent-strong);
+    }
+
+    .details {
+      padding: 0 22px 20px;
+      color: var(--muted);
+      line-height: 1.75;
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        padding: 24px 18px;
+      }
+
+      .question,
+      .details {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <h1>Cat FAQ</h1>
+    <p class="intro">
+      Quick answers to common questions about cats, from sleep habits to social behavior.
+      Select a question to reveal the answer.
+    </p>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-1">
+          <span>Why do cats sleep so much?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="faq-1" hidden>
+          <p>
+            Cats conserve energy by sleeping for long stretches, often between 12 and 16 hours a day.
+            Their ancestors were hunters that needed bursts of speed, so deep rest remains part of their rhythm.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-2">
+          <span>Why do cats purr?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="faq-2" hidden>
+          <p>
+            Purring often signals comfort, but cats may also purr when they want attention, feel nervous,
+            or are soothing themselves. Context matters, so body language helps explain what the purr means.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-3">
+          <span>Do cats recognize their owners?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="faq-3" hidden>
+          <p>
+            Yes. Cats learn familiar voices, scents, routines, and movement patterns. They may not always show
+            excitement like dogs, but many cats clearly distinguish their favorite people from strangers.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-4">
+          <span>Why do cats knead with their paws?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="faq-4" hidden>
+          <p>
+            Kneading begins in kittenhood to stimulate milk flow and often carries into adulthood as a comfort
+            behavior. Many cats knead when they feel safe, cozy, and content.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-5">
+          <span>How can you tell if a cat is stressed?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="faq-5" hidden>
+          <p>
+            Signs of stress can include hiding, flattened ears, tail flicking, unusual vocalizing, changes in
+            appetite, or avoiding the litter box. Sudden behavior changes are worth watching closely.
+          </p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    const questions = document.querySelectorAll(".question");
+
+    questions.forEach((button) => {
+      button.addEventListener("click", () => {
+        const details = document.getElementById(button.getAttribute("aria-controls"));
+        const isExpanded = button.getAttribute("aria-expanded") === "true";
+
+        button.setAttribute("aria-expanded", String(!isExpanded));
+        details.hidden = isExpanded;
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
